<?php require 'config.php'; if((int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn())exit('Admin already exists. Delete setup_admin.php and use Admin Login.');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$n=trim($_POST['name']??'');$em=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';if(!$n||!filter_var($em,FILTER_VALIDATE_EMAIL)||strlen($pw)<12)$err='Use a valid name/email and password of at least 12 characters.';else{$s=$pdo->prepare('INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)');$s->execute([$n,$em,password_hash($pw,PASSWORD_DEFAULT)]);msg('Admin created. Sign in now.');go('admin_login.php');}} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Setup</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth"><form class="glass authbox" method="post"><div class="brand">◈ NML ICH <small>Complaint Portal</small></div><h1>First Admin Setup</h1><p>Create a secure administrator account.</p><?= $err?'<div class="alert">'.e($err).'</div>':'' ?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Admin name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Password (12+ characters)</label><input type="password" name="password" minlength="12" required><button>Create Admin</button><small>After setup, delete setup_admin.php.</small></form></body></html>